#!/usr/bin/env python3
"""Copy a processed split with its low-resolution slices regenerated by k-space truncation.

The HR volumes, episode layout, info.pt and episode_mapping.json are kept, so
every trainer and scripts/evaluate_sr.py read the result like the original;
only ``obs`` in each low-res episode changes (src/data/degradation.py).

Usage:
    python scripts/make_degraded_split.py --src processed_data_mri_resub/evaluation \
        --out processed_data_mri_resub_kspace/evaluation --noise-std 0 --link
    python scripts/make_degraded_split.py --src processed_data_mri_resub/evaluation \
        --out processed_data_mri_resub_kspace_noise/evaluation --noise-std 2 --link
"""

from __future__ import annotations

import argparse
import json
import os
import shutil
import sys
from pathlib import Path

import h5py
import numpy as np
import torch

sys.path.insert(0, str(Path(__file__).resolve().parent.parent / "src"))

from data.degradation import degrade_kspace  # noqa: E402


def parse_args() -> argparse.Namespace:
    p = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--src", type=Path, required=True, help="Split root with low_res/<split> and full_res/<split>")
    p.add_argument("--out", type=Path, required=True)
    p.add_argument("--factor", type=int, default=2)
    p.add_argument("--noise-std", type=float, default=0.0, help="Complex noise std in 0-255 units (0: none)")
    p.add_argument("--seed", type=int, default=0)
    p.add_argument("--link", action="store_true", help="Hard-link the HR files instead of copying them")
    return p.parse_args()


def main() -> None:
    args = parse_args()
    splits = sorted(d.name for d in (args.src / "low_res").iterdir() if d.is_dir())
    for split in splits:
        lr_src, hr_src = args.src / "low_res" / split, args.src / "full_res" / split
        lr_out, hr_out = args.out / "low_res" / split, args.out / "full_res" / split
        lr_out.mkdir(parents=True, exist_ok=True)
        hr_out.mkdir(parents=True, exist_ok=True)
        mapping = json.loads((lr_src / "episode_mapping.json").read_text())
        for i, (episode_rel, file_id) in enumerate(sorted(mapping.items())):
            hr_name = file_id.split("/")[-1]
            with h5py.File(hr_src / hr_name, "r") as f:
                keys = sorted([k for k in f.keys() if k.endswith("_x")], key=lambda k: int(k.split("_")[1]))
                hr = np.stack([np.asarray(f[k]) for k in keys])
            d = torch.load(lr_src / episode_rel, weights_only=False)
            assert d["obs"].shape[0] == len(hr), f"{episode_rel}: {d['obs'].shape[0]} LR vs {len(hr)} HR slices"
            rng = np.random.default_rng([args.seed, i])
            lr = np.stack([degrade_kspace(s, args.factor, args.noise_std, rng) for s in hr])
            d["obs"] = torch.from_numpy(lr).unsqueeze(1)
            (lr_out / episode_rel).parent.mkdir(parents=True, exist_ok=True)
            torch.save(d, lr_out / episode_rel)
            if not (hr_out / hr_name).exists():
                (os.link if args.link else shutil.copy2)(hr_src / hr_name, hr_out / hr_name)
        for name in ("info.pt", "episode_mapping.json"):
            shutil.copy2(lr_src / name, lr_out / name)
        print(f"{split}: {len(mapping)} volumes")
    (args.out / "degradation.json").write_text(json.dumps(
        {"source": str(args.src), "method": "kspace_truncation", "factor": args.factor,
         "noise_std": args.noise_std, "seed": args.seed}, indent=2) + "\n")


if __name__ == "__main__":
    main()
